<?php
require_once __DIR__ . '/../includes/bootstrap.php';$pageTitle='Reports';$activePage='reports/index.php';$basePath='../';
$month=(string)($_GET['month']??date('Y-m'));try{[$start,$next]=month_bounds($month);}catch(Throwable $e){$month=date('Y-m');[$start,$next]=month_bounds($month);}
$stockSql="SELECT
 COALESCE(SUM(CASE WHEN movement_date < ? THEN CASE WHEN movement_type IN ('OPENING','PURCHASE','CUSTOMER_RETURN') THEN quantity ELSE -quantity END ELSE 0 END),0) opening_stock,
 COALESCE(SUM(CASE WHEN movement_date >= ? AND movement_date < ? AND movement_type IN ('PURCHASE') THEN quantity ELSE 0 END),0) purchased,
 COALESCE(SUM(CASE WHEN movement_date >= ? AND movement_date < ? AND movement_type='SALE' THEN quantity ELSE 0 END),0) sold,
 COALESCE(SUM(CASE WHEN movement_date >= ? AND movement_date < ? AND movement_type='INTERNAL_USE' THEN quantity ELSE 0 END),0) internal_use,
 COALESCE(SUM(CASE WHEN movement_date >= ? AND movement_date < ? AND movement_type='DAMAGE' THEN quantity ELSE 0 END),0) damaged,
 COALESCE(SUM(CASE WHEN movement_date >= ? AND movement_date < ? AND movement_type='CUSTOMER_RETURN' THEN quantity ELSE 0 END),0) customer_returns,
 COALESCE(SUM(CASE WHEN movement_date >= ? AND movement_date < ? AND movement_type='SUPPLIER_RETURN' THEN quantity ELSE 0 END),0) supplier_returns,
 COALESCE(SUM(CASE WHEN movement_date < ? THEN CASE WHEN movement_type IN ('OPENING','PURCHASE','CUSTOMER_RETURN') THEN quantity ELSE -quantity END WHEN movement_date >= ? AND movement_date < ? THEN CASE WHEN movement_type IN ('OPENING','PURCHASE','CUSTOMER_RETURN') THEN quantity ELSE -quantity END ELSE 0 END),0) closing_stock,
 COALESCE(SUM(CASE WHEN movement_date < ? THEN CASE WHEN movement_type IN ('OPENING','PURCHASE','CUSTOMER_RETURN') THEN quantity*unit_cost ELSE -quantity*unit_cost END WHEN movement_date >= ? AND movement_date < ? THEN CASE WHEN movement_type IN ('OPENING','PURCHASE','CUSTOMER_RETURN') THEN quantity*unit_cost ELSE -quantity*unit_cost END ELSE 0 END),0) closing_value
 FROM stock_movements";
$params=[$start,$start,$next,$start,$next,$start,$next,$start,$next,$start,$next,$start,$next,$next,$start,$next,$next,$start,$next];$st=$pdo->prepare($stockSql);$st->execute($params);$stock=$st->fetch();
$st=$pdo->prepare('SELECT COUNT(DISTINCT p.purchase_id) transactions,COALESCE(SUM(pi.quantity),0) quantity,COALESCE(SUM(pi.quantity*pi.unit_cost),0) expenditure FROM purchases p JOIN purchase_items pi ON pi.purchase_id=p.purchase_id WHERE p.purchase_date>=? AND p.purchase_date<?');$st->execute([$start,$next]);$purchase=$st->fetch();
$st=$pdo->prepare('SELECT COUNT(DISTINCT s.sale_id) transactions,COALESCE(SUM(si.quantity),0) quantity,COALESCE(SUM(si.quantity*si.unit_selling_price),0) revenue,COALESCE(SUM(si.quantity*si.unit_cost_at_sale),0) cogs FROM sales s JOIN sale_items si ON si.sale_id=s.sale_id WHERE s.sale_date>=? AND s.sale_date<?');$st->execute([$start,$next]);$sale=$st->fetch();$gross=(float)$sale['revenue']-(float)$sale['cogs'];
$st=$pdo->prepare('SELECT p.product_name,p.unit,SUM(pi.quantity) quantity,SUM(pi.quantity*pi.unit_cost) expenditure FROM purchase_items pi JOIN purchases pu ON pu.purchase_id=pi.purchase_id JOIN products p ON p.product_id=pi.product_id WHERE pu.purchase_date>=? AND pu.purchase_date<? GROUP BY p.product_id ORDER BY expenditure DESC');$st->execute([$start,$next]);$purchaseProducts=$st->fetchAll();
$st=$pdo->prepare('SELECT p.product_name,p.unit,SUM(si.quantity) quantity,SUM(si.quantity*si.unit_selling_price) revenue,SUM(si.quantity*si.unit_cost_at_sale) cogs FROM sale_items si JOIN sales sa ON sa.sale_id=si.sale_id JOIN products p ON p.product_id=si.product_id WHERE sa.sale_date>=? AND sa.sale_date<? GROUP BY p.product_id ORDER BY quantity DESC');$st->execute([$start,$next]);$salesProducts=$st->fetchAll();
$low=$pdo->query('SELECT * FROM Low_Stock_Products ORDER BY quantity_available ASC')->fetchAll();$dead=$pdo->query('SELECT * FROM Dead_Stock_Products ORDER BY days_without_sale DESC')->fetchAll();
require __DIR__.'/../includes/header.php';?>
<section class="page-heading"><div><p class="eyebrow">BUSINESS PERFORMANCE</p><h1>Reports</h1><p class="muted">Monthly stock, purchase, sales and gross-profit calculations.</p></div><form method="get" class="month-picker"><label>Reporting month<input type="month" name="month" value="<?=e($month)?>"></label><button class="btn primary">Generate</button></form></section>
<div class="stats-grid compact"><article class="stat-card"><span>Opening stock</span><strong><?=qty($stock['opening_stock'])?></strong><small>Units across mixed measures</small></article><article class="stat-card"><span>Closing stock</span><strong><?=qty($stock['closing_stock'])?></strong><small>Calculated from movement history</small></article><article class="stat-card"><span>Purchase expenditure</span><strong><?=money($purchase['expenditure'])?></strong><small><?= (int)$purchase['transactions'] ?> purchase invoices</small></article><article class="stat-card"><span>Sales revenue</span><strong><?=money($sale['revenue'])?></strong><small><?= (int)$sale['transactions'] ?> sales bills</small></article><article class="stat-card"><span>Cost of goods sold</span><strong><?=money($sale['cogs'])?></strong><small>Saved unit cost at sale time</small></article><article class="stat-card"><span>Gross profit</span><strong class="<?= $gross<0?'text-danger':'text-success' ?>"><?=money($gross)?></strong><small>Revenue less COGS</small></article><article class="stat-card"><span>Closing inventory value</span><strong><?=money($stock['closing_value'])?></strong><small>Valued from costed stock movements</small></article></div>
<div class="two-column"><section class="panel"><h2>Stock summary</h2><div class="table-wrap"><table><tbody><?php $stockRows=[['Opening stock',$stock['opening_stock']],['Purchased',$stock['purchased']],['Sold',$stock['sold']],['Internal usage',$stock['internal_use']],['Damaged',$stock['damaged']],['Customer returns',$stock['customer_returns']],['Supplier returns',$stock['supplier_returns']],['Closing stock',$stock['closing_stock']]];foreach($stockRows as $r):?><tr><td><?=e($r[0])?></td><td class="number"><?=qty($r[1])?></td></tr><?php endforeach;?></tbody></table></div><p class="field-note">Stock totals combine kg, litres, packets and pieces. Use product-wise reports when comparing units.</p></section>
<section class="panel"><h2>Financial summary</h2><div class="financial-list"><div><span>Purchase expenditure</span><strong><?=money($purchase['expenditure'])?></strong></div><div><span>Sales revenue</span><strong><?=money($sale['revenue'])?></strong></div><div><span>Cost of goods sold</span><strong><?=money($sale['cogs'])?></strong></div><div class="emphasis"><span>Gross profit</span><strong><?=money($gross)?></strong></div><div><span>Closing inventory value</span><strong><?=money($stock['closing_value'])?></strong></div></div><p class="field-note">Purchase expenditure is not deducted directly to calculate gross profit. Gross profit = sales revenue − COGS.</p></section></div>
<div class="two-column"><section class="panel"><h2>Product-wise purchases</h2><div class="table-wrap"><table><thead><tr><th>Product</th><th>Quantity</th><th>Expenditure</th></tr></thead><tbody><?php foreach($purchaseProducts as $r):?><tr><td><?=e($r['product_name'])?></td><td><?=qty($r['quantity'])?> <?=e($r['unit'])?></td><td><?=money($r['expenditure'])?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><h2>Product-wise sales</h2><div class="table-wrap"><table><thead><tr><th>Product</th><th>Quantity</th><th>Revenue</th><th>COGS</th></tr></thead><tbody><?php foreach($salesProducts as $r):?><tr><td><?=e($r['product_name'])?></td><td><?=qty($r['quantity'])?> <?=e($r['unit'])?></td><td><?=money($r['revenue'])?></td><td><?=money($r['cogs'])?></td></tr><?php endforeach;?></tbody></table></div></section></div>
<div class="two-column"><section class="panel"><div class="panel-heading"><h2>Low-stock products</h2><span class="count-label"><?=count($low)?></span></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Available</th><th>Reorder level</th></tr></thead><tbody><?php foreach($low as $r):?><tr><td><?=e($r['product_name'])?></td><td><?=qty($r['quantity_available'])?> <?=e($r['unit'])?></td><td><?=qty($r['reorder_level'])?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><div class="panel-heading"><h2>Dead-stock products</h2><span class="count-label"><?=count($dead)?></span></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Stock</th><th>Days inactive</th></tr></thead><tbody><?php foreach($dead as $r):?><tr><td><?=e($r['product_name'])?><small class="subline"><?=e($r['reason'])?></small></td><td><?=qty($r['quantity_available'])?> <?=e($r['unit'])?></td><td><?= (int)$r['days_without_sale'] ?></td></tr><?php endforeach;?></tbody></table></div></section></div>
<?php require __DIR__.'/../includes/footer.php';?>
